@php $locale=app()->getLocale(); $base='public.'.$pageKey; $current=$locale==='fa'?route($base.'.fa'):route($base,['locale'=>$locale]); $alt=fn($l)=>$l==='fa'?route($base.'.fa'):route($base,['locale'=>$l]); $pageFaqs=$pageKey==='faq'?__('site.faqs'):($content['faqs']??[]); @endphp
<!doctype html><html lang="{{ $locale }}" dir="{{ in_array($locale,['fa','ar'],true)?'rtl':'ltr' }}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#2947a3"><meta name="robots" content="index,follow,max-image-preview:large"><title>{{ $content['meta_title'] }}</title><meta name="description" content="{{ $content['meta_description'] }}"><link rel="canonical" href="{{ $current }}">@foreach(['fa','ar','en'] as $l)<link rel="alternate" hreflang="{{ $l }}" href="{{ $alt($l) }}">@endforeach<link rel="alternate" hreflang="x-default" href="{{ $alt('fa') }}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/font.css?v=20260912"><link rel="stylesheet" href="/assets/site.css?v=20260912"><script src="/assets/site.js?v=20260912" defer></script></head><body>@include('public.partials.header')<main id="main"><section class="page-hero"><div class="shell narrow"><h1>{{ $content['title'] }}</h1><p>{{ $content['lead'] }}</p></div></section>@if($pageKey==='services')<section class="section white"><div class="shell"><div class="service-links large-services">@foreach($content['services'] as $service)<a class="service-link" href="{{ $locale==='fa'?route($service['route'].'.fa'):route($service['route'],['locale'=>$locale]) }}"><img src="/assets/{{ $service['icon'] }}" alt=""><span><strong>{{ $service['title'] }}</strong><small>{{ $service['text'] }}</small></span><b>←</b></a>@endforeach</div></div></section>@endif @foreach($content['sections']??[] as $index=>$section)<section class="section {{ $index%2?'white':'' }}"><div class="shell content-section"><div><h2>{{ $section['title'] }}</h2>@if(!empty($section['body']))<p class="large-copy">{{ $section['body'] }}</p>@endif</div>@if(!empty($section['items']))<div class="info-list">@foreach($section['items'] as $item)<article><span>{{ str_pad((string)($loop->index+1),2,'0',STR_PAD_LEFT) }}</span><div><strong>{{ is_